// Block (composition) — a ready-to-use new-password form assembled from Components.
// Contract: docs/rules/block-contract.md. Arranges only (Stack for layout);
// composes Form/TextField/Button/Alert. Owns no Component look; mints no tokens.
import type { FormEvent, Ref } from "react";
import { Form } from "../components/Form";
import { TextField } from "../components/TextField";
import { Button } from "../components/Button";
import { Alert } from "../components/Alert";
import { Stack } from "../layouts/Stack";
import "./ResetPasswordForm.css";

export interface ResetPasswordFormProps {
  /** Heading shown above the fields. */
  heading?: string;
  /** Called with the entered passwords on submit. */
  onSubmit?: (values: { password: string; confirmPassword: string }) => void;
  /** Form-level error, shown above the fields. */
  errorMessage?: string;
  /** Puts the submit button in a pending state and blocks re-submit. */
  isPending?: boolean;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function ResetPasswordForm({
  heading = "Set a new password",
  onSubmit,
  errorMessage,
  isPending,
  className,
  ref,
}: ResetPasswordFormProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      password: String(data.get("password") ?? ""),
      confirmPassword: String(data.get("confirmPassword") ?? ""),
    });
  };

  return (
    <Form isPending={isPending}
      ref={ref}
      onSubmit={handleSubmit}
      className={className ? `sd-resetpasswordform ${className}` : "sd-resetpasswordform"}
    >
      <Stack gap="large" className="sd-resetpasswordform__content">
        {heading && (
          <>
            <h1 className="sd-resetpasswordform__heading sd-type-headline-medium">{heading}</h1>
          </>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Stack gap="medium" className="sd-resetpasswordform__fields">
          <TextField
            label="Password"
            name="password"
            type="password"
            autoComplete="new-password"
            isRequired
          />
          <TextField
            label="Confirm password"
            name="confirmPassword"
            type="password"
            autoComplete="new-password"
            isRequired
          />
        </Stack>
        <Button size="large" type="submit" variant="primary" isPending={isPending}>
          Update password
        </Button>
      </Stack>
    </Form>
  );
}

/* ResetPasswordForm.css — .sd-resetpasswordform (Block)
   Arrangement only: fills the column it is given; the page sets that column on the grid
   (a Container span or a LayoutGrid item), never this Block.
   Component look is owned by Form/TextField/Button/Alert; grouping is via Stack.
   No new tokens. */
.sd-resetpasswordform {
  width: 100%;
}

.sd-resetpasswordform__heading {
  margin: 0;
}
